using System;

public class Program
{
    public static void Main()
    {
        double allKm = 0;
        int trips = 0;
        for (int d = 1; d <= 19; d++)
        {
            double km = 0;
            double x = double.Parse(Console.ReadLine());
            while (x >= 0)
            {
                km += x;
                trips++;
                x = double.Parse(Console.ReadLine());
            }
            Console.WriteLine(Math.Round(km, 2));
            Console.WriteLine(Math.Round(km / 10, 2));
            allKm += km;
        }
        Console.WriteLine(Math.Round(allKm / trips, 2));
    }
}
